-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.monk.brewmaster.Name"] = "推荐"
L["rm.mop.monk.brewmaster.Description"] = "在酒仙专精中自动选择。用幻灭踢保持酒醒入定，真气容得下时就使用醉酿投，受伤时使用移花接木（低于 35% 时立即使用），用贯日击消耗能量，猛虎掌用于猛虎之力以及作为免费填充（34 级前由贯日击攒真气），轮回之触可用时使用。脱战时从远处：真气波、迷醉酒雾、对冲或醉酿投。三个或更多敌人时：碧玉疾风、火焰之息，神鹤引项踢仅在酒醒入定还有剩余时间时使用。提醒：磐牛式、帝王传承、重度醉拳时使用活血酒（酒醒入定时间充裕时中度醉拳也用）、飘渺酒六层起使用、有强力金钟罩时使用金钟罩、真气酒、白虎下凡、生命值低时使用壮胆酒、躯不坏或散魔功、切喉手。玄牛雕像的提醒为关闭状态；慈悲庇护、禅悟冥想和嚎镇八方由你自己掌控。"
L["rm.mop.monk.brewmaster.offensive.Name"] = "伤害优先（模拟器）"
L["rm.mop.monk.brewmaster.offensive.Description"] = "作为酒仙内置循环的替代，默认关闭：启用它并禁用那个，或提高它的优先级。遵循模拟器为装备远超当前内容的坦克提供的伤害优先列表：碧玉疾风先于醉酿投，真气用于幻灭踢造成伤害，不再常规使用活血酒或金钟罩（活血酒只在 T15 的活血化瘀触发时亮起）。飘渺酒、真气酒、白虎下凡和壮胆酒仍会提醒。"
L["rm.mop.monk.mistweaver.Name"] = "推荐"
L["rm.mop.monk.mistweaver.Description"] = "在织雾专精中自动选择。选中友方目标时治疗该目标：复苏之雾冷却完毕即用，附近有三名或更多盟友受伤时使用振魂引，用移花接木和你的真气天赋获取真气，队伍受伤时使用碧玉疾风或神鹤引项踢，活力之雾达到五层时使用升腾之雾，目标低于 80% 时使用抚慰之雾，然后在引导期间使用氤氲之雾和升腾之雾。选中敌对目标时进行拳疗：熟能生巧触发时使用猛虎掌和幻灭踢以保持猛虎之力和青龙之忱，真气满时使用幻灭踢，活力之雾达到五层时使用升腾之雾，用复苏之雾和移花接木获取真气，贯日击。提醒：灵龙式、帝王传承、组队时的青龙雕像、空闲时使用法力茶、雷光聚神茶、真气酒、对低于 35% 的友方使用作茧缚命、白虎下凡、化瘀术、防御技能、切喉手。治疗谁由你选择；还魂术（提醒为关闭状态）和疗伤珠由你自己掌控。"
L["rm.mop.monk.unspecialized.Name"] = "选择专精前"
L["rm.mop.monk.unspecialized.Description"] = "适用于 1 至 9 级，或尚未选择专精的武僧；选择专精后由专精内置循环接管。保持猛虎式和猛虎之力，消耗两点真气施放幻灭踢，受伤时使用移花接木，否则使用贯日击。"
L["rm.mop.monk.windwalker.Name"] = "推荐"
L["rm.mop.monk.windwalker.Description"] = "在踏风专精中自动选择。轮回之触可用时使用，猛虎掌保持猛虎之力，旭日东升踢冷却完毕即用，真气波，踏风连击触发，你站立不动且引导不会让能量溢出时使用怒雷破，缺少两点真气时使用贯日击（受伤时改用移花接木），在不耽误下一次旭日东升踢的前提下使用幻灭踢。两个或更多敌人时旭日东升踢保持其减益效果，三个起加入神鹤引项踢或碧玉疾风。提醒：猛虎式、帝王传承和白虎传承、虎眼酒 19 层时使用（有真气可用时 15 层，嗜血期间或战斗接近尾声时 10 层）、能量低时使用豪能酒、真气酒、白虎下凡、两个敌人时使用风火雷电（对第二个敌人施放）、业报之触、防御技能和切喉手。能量溢出检查使用的是能量阈值，因此请按你的急速调整它们。"
L["rm.mop.monk.windwalker.simc.Name"] = "SimulationCraft 5.4.8（Hekili 和 MaxDps）"
L["rm.mop.monk.windwalker.simc.Description"] = "作为踏风内置循环的替代，默认关闭：启用它并禁用那个，或提高它的优先级。Hekili 和 MaxDps 插件自带的原版 SimulationCraft 列表：猛虎之力在剩余三秒时刷新，旭日东升踢的减益效果缺失时优先使用，怒雷破留给虎眼酒（生效中或达到 15 层），虎眼酒在 20 层时，或 15 层且有真气、两个增益效果都生效时使用。三个或更多敌人时把资源花在神鹤引项踢上，仅在真气满时使用旭日东升踢，能量低于 60 时攒能量。"
L["rm.retail.monk.brewmaster.Name"] = "暴雪战斗辅助，含酒类技能"
L["rm.retail.monk.brewmaster.Description"] = "推荐酒仙专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。战斗辅助不会使用任何酒类技能，因此按照 Icy Veins 的建议，酒类技能以提醒的形式显示在它旁边：玄牛酒、玄牛下凡、活血酒、天神酒或天神灌注以及轮回之触会在战斗中一旦就绪就亮起（Rotation Master 目前还无法读取醉拳，因此醉拳有多重仍由你判断）。另外还有对可打断的施法使用切喉手，以及战斗中一就绪就使用的壮胆酒和你的种族冷却技能；敌人的施法在战斗中是隐藏的，因此打断提醒只在游戏显示它们的场合亮起，生命值在正式服中是隐藏的，因此何时使用壮胆酒由你自己决定。"
L["rm.retail.monk.brewmaster.guide.Name"] = "参考（Icy Veins）"
L["rm.retail.monk.brewmaster.guide.Description"] = "仅供参考，默认关闭：Icy Veins 的酒仙优先级（SimulationCraft 的思路大体一致）。幻灭连击、空酒桶和充能在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行。以醉酿投拉怪。幻灭踢；真气爆裂（祥和宗师）；幻灭连击触发时使用猛虎掌；充能已满或有空酒桶时使用醉酿投；火焰之息；在爆炸酒桶之前使用碧玉疾风；真气爆裂（影踪派）；醉酿投；三个或更多敌人时使用碧玉疾风和神鹤引项踢；猛虎掌；移花接木。提醒：活血酒和天神酒都用完后使用玄牛酒、玄牛下凡、活血酒、天神酒或天神灌注、轮回之触以及功能性提醒。"
L["rm.retail.monk.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.monk.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是武僧的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有武僧内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.monk.mistweaver.Name"] = "参考（Icy Veins）"
L["rm.retail.monk.mistweaver.Description"] = "仅供参考，默认关闭。暴雪没有为治疗者提供战斗辅助列表，而且在至暗之夜的战斗中，盟友的生命值、复苏之雾的充能、法力茶的层数和触发效果都对插件隐藏，因此无法给出治疗建议；请自行选择治疗技能。对敌对目标时，它会建议踢疗的填充技能：旭日东升踢、幻灭踢和猛虎掌；对友方目标或没有目标时不建议任何技能。提醒：切喉手，以及战斗中一就绪就使用的壮胆酒和你的种族冷却技能。"
L["rm.retail.monk.windwalker.Name"] = "暴雪战斗辅助"
L["rm.retail.monk.windwalker.Description"] = "推荐踏风专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议（它本身就会维持精通：组合拳）；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的乾元之巅、天神御身、白虎下凡和业报之触、对可打断的施法使用切喉手，以及战斗中一就绪就使用的壮胆酒和你的种族冷却技能。敌人的施法在战斗中是隐藏的，因此打断提醒只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用壮胆酒由你自己决定。"
L["rm.retail.monk.windwalker.guide.Name"] = "参考（Icy Veins 和 SimulationCraft）"
L["rm.retail.monk.windwalker.guide.Description"] = "仅供参考，默认关闭：Icy Veins 的天神御师优先级。每一步都会维持精通：组合拳（从不重复上一个施放的法术）；真气和你自己的施法仍可读取，但青龙之心、乾元之巅、幻灭踢！和赤精之舞在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行；能量在正式服中是隐藏的，所以能量溢出前的猛虎掌被省略了。白虎下凡还有 10 秒以上才就绪时使用升龙霸；真气不足或乾元之巅即将结束时使用乾元镇踏；没有青龙之心时使用天神御身；青龙之心即将结束时使用怒雷破；天神御身、白虎下凡、怒雷破、升龙霸、风领主之击；真气不够施放怒雷破时使用幻灭踢；疾风呼啸踢、旭日东升踢；有两层幻灭踢！充能或在乾元之巅期间使用幻灭踢；乾元之巅期间或赤精之舞触发时使用神鹤引项踢；轮回之触；猛虎掌、幻灭踢、切削之风作为填充。提醒：业报之触以及功能性提醒。"
